/** Neutral surfaces of a signature theme or of the Slate and Sea style (instead of Telegram's blue night / plain day); null = keep the default. */
internal class Neutrals(
    val background: Color,
    val surfaceVariant: Color,
    val onSurfaceVariant: Color,
    val topBar: Color,
    val onTopBar: Color?,
    val onTopBarMuted: Color,
    val drawerHeader: Color?,
