    val container: Color,
    val containerHighest: Color,
    val online: Color?,
)

/**
 * Surfaces by precedence: a house that defines neutrals for the mode, else Slate and Sea (its graphite night when
 * [elegant] is on), else the elegant night ones when [elegant] is on; null = the default Telegram look. (Dynamic colours drop all of them in the caller.)
 */
internal fun neutralsOf(style: TatrakStyle, accent: Accent, dark: Boolean, elegant: Boolean): Neutrals? =
    (if (dark) night[accent] else day[accent])
        ?: if (style == TatrakStyle.SLATE_SEA) (if (!dark) slateDay else if (elegant) slateElegantNight else slateNight) else elegantNight.takeIf { dark && elegant }

